<?php
require 'config.php';require 'includes/functions.php';require_admin();verify_csrf();$statuses=['Pending','Processing','Completed','Cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['order_id']??0);$st=$_POST['status']??'';if(in_array($st,$statuses,true)){$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$st,$id]);$_SESSION['flash']='Order fulfilment status updated.';}redirect('admin-orders.php');}
$orders=$pdo->query('SELECT * FROM orders ORDER BY created_at DESC')->fetchAll();$pageTitle='Manage orders';require 'includes/header.php';?>
<div class="section-head"><div><div class="eyebrow">Administration</div><h1>Manage orders</h1></div><a class="btn btn-light" href="admin-dashboard.php">Dashboard</a></div><div class="panel"><p>Payment status is controlled by verified PayFast notifications. You may update fulfilment status separately.</p><?php if(!$orders):?><p class="muted">No orders yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Member</th><th>Contact / address</th><th>Items</th><th>Total</th><th>Payment</th><th>Fulfilment status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?><br><span class="small muted"><?=e($o['created_at'])?></span></td><td><?=e($o['member_name'])?><br><?=e($o['member_code'])?></td><td><?=e($o['contact'])?><br><?=nl2br(e($o['delivery_address']))?></td><td><?php $s=$pdo->prepare('SELECT product_name,quantity FROM order_items WHERE order_id=?');$s->execute([$o['id']]);foreach($s->fetchAll() as $it)echo e($it['product_name']).' × '.(int)$it['quantity'].'<br>';?></td><td><?=money($o['total'])?></td><td><span class="status <?=e($o['payment_status'])?>"><?=e($o['payment_status'])?></span><?php if($o['payfast_payment_id']):?><br><span class="small muted">PayFast ref: <?=e($o['payfast_payment_id'])?></span><?php endif;?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=$o['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach($statuses as $st):?><option <?=$o['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require 'includes/footer.php';?>